$db = \Illuminate\Support\Facades\DB::table('crm_deliveries');
$claimed = (clone $db)->where('id', $this->deliveryId)->where('state', 'pending')->update([
    'state' => 'sending', 'attempted_at' => now(),
    'attempts' => \Illuminate\Support\Facades\DB::raw('attempts + 1'),
]);
if ($claimed !== 1) return;
$row = (clone $db)->where('id', $this->deliveryId)->first();
$fields = json_decode($row->fields, true, 32, JSON_THROW_ON_ERROR);
$fields['ORIGINATOR_ID'] = 'telegram_consultations';
$fields['ORIGIN_ID'] = $row->request_id;
$outcome = app(\App\Services\BitrixLeads::class)->create($fields);
(clone $db)->where('id', $row->id)->where('state', 'sending')->update([
    'state' => $outcome['state'], 'crm_lead_id' => $outcome['crm_lead_id'] ?? null,
    'last_error' => $outcome['code'] ?? null,
]);

use App\Jobs\SendLeadToBitrix;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schedule;

Schedule::call(function () {
    DB::table('crm_deliveries')->where('state', 'pending')->orderBy('id')->limit(100)
        ->pluck('id')->each(fn ($id) => SendLeadToBitrix::dispatch((int) $id)->onQueue('crm'));
})->everyMinute()->withoutOverlapping();
